import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        Solver s = new Solver();
        s.solve(in, out);
        out.close();
    }

    static class Solver {
        private int countTokensInRange(String s, int start, int end) {
            int count = 0;
            boolean inToken = false;
            for (int k = start; k < end; k++) {
                if (s.charAt(k) == '_') {
                    inToken = false;
                } else if (!inToken) {
                    inToken = true;
                    count++;
                }
            }
            return count;
        }

        public void solve(Scanner in, PrintWriter out) {
            int n = in.nextInt();
            String s = in.next();
            int winpars = 0, longest = 0;
            int i = 0, j = 0;

            while (s.contains("__")) {
                s = s.replaceAll("__", "_");
            }
            n = s.length();

            if (s.charAt(i) == '(') {
                while (j < n && s.charAt(j++) != ')') {
                    if (s.charAt(j) == ')') {
                        winpars += countTokensInRange(s, i + 1, j);
                        i = j;
                    }
                }
            }

            while (i < n && s.charAt(i) != '(') {
                ++i;
                if (i < n && s.charAt(i) == '(') {
                    j = i;
                    while (j < n && s.charAt(j++) != ')') {
                        if (s.charAt(j) == ')') {
                            winpars += countTokensInRange(s, i + 1, j);
                            i = j;
                        }
                    }
                }
            }

            while (s.indexOf('(') != -1 || s.indexOf(')') != -1) {
                s = s.replaceAll("\\([^\\(]*\\)", "_");
            }

            StringTokenizer tok = new StringTokenizer(s, "_");
            while (tok.hasMoreTokens()) {
                String temp = tok.nextToken();
                if (temp.length() > longest) {
                    longest = temp.length();
                }
            }

            out.println(longest + " " + winpars);
        }
    }
}
